// JSON in C++ bauen und ausgeben
#include <nlohmann/json.hpp>
#include <iostream>

using json = nlohmann::json;

int main() {
    json daten = {
        {"name", "Lernpfad"},
        {"level", 3},
        {"aktiv", true},
        {"themen", {"Python", "C++"}}
    };

    std::cout << daten.dump(2) << std::endl;  // schöner Text

    std::string name = daten["name"].get<std::string>();
    std::cout << name << std::endl;           // Lernpfad
    return 0;
}

// JSON-Datei schreiben und lesen (C++)
#include <nlohmann/json.hpp>
#include <iostream>
#include <fstream>

using json = nlohmann::json;

int main() {
    json spielstand = {
        {"spieler", "Alex"},
        {"level", 7},
        {"punkte", 1250},
        {"items", {"Schwert", "Schild"}}
    };

    // Schreiben:
    std::ofstream aus("spielstand.json");
    aus << spielstand.dump(2);
    aus.close();

    // Lesen:
    std::ifstream ein("spielstand.json");
    if (!ein) { std::cerr << "Datei fehlt!" << std::endl; return 1; }
    json geladen = json::parse(ein);

    std::cout << geladen["spieler"] << std::endl;  // Alex
    return 0;
}

// JSON-Fehler abfangen (C++)
#include <nlohmann/json.hpp>
#include <iostream>

using json = nlohmann::json;

int main() {
    std::string kaputt = R"({
        'name': 'Alex',
        'level': 3,
    })";

    try {
        json daten = json::parse(kaputt);
    } catch (const json::parse_error& e) {
        std::cerr << "JSON-Fehler: " << e.what() << std::endl;
    }
    return 0;
}

// JSON als Konfiguration nutzen (C++)
#include <nlohmann/json.hpp>
#include <iostream>
#include <fstream>

using json = nlohmann::json;

int main() {
    std::ifstream datei("config.json");
    json config = json::parse(datei);

    int lautstaerke = config["lautstaerke"];
    std::string sprache = config["sprache"].get<std::string>();

    std::cout << "Sprache: " << sprache << std::endl;
    std::cout << "Lautstärke: " << lautstaerke << std::endl;
    return 0;
}
